<?php
require_login();
$user = current_user();
$isAdmin = ($user['role'] ?? '') === 'admin';
$noticeFile = DATA_PATH . '/cm_docs.json';

function cds_notice_fields(): array {
    return [
        'chung' => ['label'=>'Thông báo chung','color'=>'#475569','module'=>''],
        'chuyenmon' => ['label'=>'Chuyên môn','color'=>'#2563eb','module'=>'chuyenmon'],
        'vanban' => ['label'=>'Văn bản · Hành chính','color'=>'#7c3aed','module'=>'vanban'],
        'noitru' => ['label'=>'Nội trú','color'=>'#be185d','module'=>'noitru'],
        'thuvien' => ['label'=>'Thư viện · Thiết bị','color'=>'#0f766e','module'=>'thuvien'],
        'thidua' => ['label'=>'Thi đua','color'=>'#b45309','module'=>'thidua'],
        'csdl' => ['label'=>'Cơ sở dữ liệu','color'=>'#0369a1','module'=>'csdl'],
    ];
}
function cds_notice_can_field(string $key): bool {
    $user=current_user(); if(($user['role']??'')==='admin') return true;
    $f=cds_notice_fields()[$key]??null; if(!$f) return false;
    if($key==='chung') return false;
    $module=(string)($f['module']??'');
    return $module!=='' && can_module($module,'edit');
}
function cds_notice_allowed_fields(): array {return array_filter(cds_notice_fields(),fn($v,$k)=>cds_notice_can_field((string)$k),ARRAY_FILTER_USE_BOTH);}
function cds_notice_rows_all(): array { $rows=cds_json_load(DATA_PATH.'/cm_docs.json',[]); return is_array($rows)?$rows:[]; }
function cds_notice_save_all(array $rows): bool { return cds_json_save(DATA_PATH.'/cm_docs.json',array_values($rows)); }
function cds_notice_rows(): array {
    $out=[]; foreach(cds_notice_rows_all() as $r){ if(($r['section']??'')!=='kh_thongbao') continue; if(empty($r['field']))$r['field']='chuyenmon'; $out[]=$r; }
    usort($out,fn($a,$b)=>strcmp((string)($b['date']??''),(string)($a['date']??''))?:strcmp((string)($b['created_at']??''),(string)($a['created_at']??''))); return $out;
}
function cds_notice_file_url(string $path): string { if($path==='')return ''; return str_starts_with($path,'gdrive:')?BASE_URL.'admin.php?drive_file='.rawurlencode(substr($path,7)):BASE_URL.'data/'.ltrim($path,'/'); }
function cds_notice_upload(string $field,string $category='plans'): string {
    $up=$_FILES[$field]??null; if(!$up||($up['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return '';
    if(($up['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK)throw new RuntimeException('Không nhận được file tải lên. Mã lỗi '.(int)$up['error'].'.');
    $tmp=(string)($up['tmp_name']??''); $bytes=$tmp!==''?@file_get_contents($tmp):false; if($bytes===false)throw new RuntimeException('Không đọc được file tạm trên máy chủ.');
    if(strlen($bytes)>25*1024*1024)throw new RuntimeException('File vượt quá 25 MB.');
    $settings=cds_drive_settings(); $folder=trim((string)($settings['types'][$category]['folder_id']??''));
    if(empty($settings['enabled'])||$folder==='')throw new RuntimeException('Google Drive chưa bật hoặc chưa cấu hình thư mục “Kế hoạch và báo cáo”.');
    $mime=function_exists('mime_content_type')?(mime_content_type($tmp)?:'application/octet-stream'):'application/octet-stream';
    $result=cds_drive_upload_bytes($bytes,basename((string)($up['name']??'file')),$mime,$category,['action'=>'notice','source_action'=>'page:/admin.php?view=notices']);
    if(empty($result['ok']))throw new RuntimeException((string)($result['message']??'Không tải được file lên Google Drive.'));
    return (string)($result['path']??('gdrive:'.($result['id']??'')));
}

$allowedFields=cds_notice_allowed_fields();
if(!$allowedFields){http_response_code(403);echo '<div style="font-family:system-ui;padding:2rem">Bạn chưa được phân quyền đăng thông báo.</div>';exit;}

if($_SERVER['REQUEST_METHOD']==='POST'){
    $ajax=!empty($_POST['notice_ajax']);
    try{
        $action=(string)($_POST['notice_action']??'');
        if($action==='save'){
            $field=(string)($_POST['field']??''); if(!isset($allowedFields[$field]))throw new RuntimeException('Bạn không có quyền đăng ở lĩnh vực đã chọn.');
            $id=trim((string)($_POST['id']??'')); $new=$id===''; if($new)$id='cm_'.date('YmdHis').'_'.bin2hex(random_bytes(4));
            $title=trim((string)($_POST['title']??'')); if($title==='')throw new RuntimeException('Hãy nhập tiêu đề thông báo.');
            $rows=cds_notice_rows_all(); $old=null; foreach($rows as $r)if(($r['id']??'')===$id){$old=$r;break;}
            $file=cds_notice_upload('file','plans'); $oldFile=trim((string)($_POST['file_path']??($old['file_path']??'')));
            $hasDeadline=!empty($_POST['has_deadline']); $hasAssignees=!empty($_POST['has_assignees']);
            $assignees=$hasAssignees?array_values(array_filter(array_map('trim',(array)($_POST['assignees']??[])))):[];
            $record=array_merge(is_array($old)?$old:[],[
                'id'=>$id,'section'=>'kh_thongbao','kind'=>'notice','field'=>$field,'title'=>$title,
                'date'=>trim((string)($_POST['date']??date('Y-m-d'))),'has_deadline'=>$hasDeadline,
                'due_date'=>$hasDeadline?trim((string)($_POST['due_date']??'')):'','day_from'=>'','day_to'=>'',
                'has_assignees'=>$hasAssignees,'assignees'=>$assignees,'completed'=>!empty($_POST['completed']),
                'content'=>trim((string)($_POST['content']??'')),'link'=>trim((string)($_POST['link']??'')),
                'file_path'=>$file!==''?$file:$oldFile,'by'=>$user['name']??'','updated_at'=>date('c')
            ]); if($new)$record['created_at']=date('c');
            $found=false; foreach($rows as &$r)if(($r['id']??'')===$id){$r=$record;$found=true;break;}unset($r); if(!$found)$rows[]=$record;
            if(!cds_notice_save_all($rows))throw new RuntimeException('Không lưu được dữ liệu thông báo.');
            if($new&&!$record['completed'])cds_push_publish($title,mb_strimwidth(strip_tags((string)$record['content']),0,180,'…','UTF-8'),'/admin.php?view=notices&notice='.rawurlencode($id),['source_id'=>'notice:'.$id,'audience'=>['all'],'expires_at'=>$record['due_date']]);
            $message=$file!==''?'Đã tải file lên Google Drive và lưu thông báo.':'Đã lưu thông báo.';
        } elseif($action==='toggle'){
            $id=(string)($_POST['id']??'');$rows=cds_notice_rows_all();$ok=false;foreach($rows as &$r)if(($r['id']??'')===$id&&($r['section']??'')==='kh_thongbao'){if(!cds_notice_can_field((string)($r['field']??'chuyenmon')))throw new RuntimeException('Bạn không có quyền cập nhật thông báo này.');$r['completed']=empty($r['completed']);$r['updated_at']=date('c');$ok=true;break;}unset($r);if(!$ok)throw new RuntimeException('Không tìm thấy thông báo.');cds_notice_save_all($rows);$message='Đã cập nhật trạng thái.';
        } elseif($action==='delete'){
            $id=(string)($_POST['id']??'');$rows=cds_notice_rows_all();$kept=[];$found=false;foreach($rows as $r){if(($r['id']??'')===$id&&($r['section']??'')==='kh_thongbao'){if(!cds_notice_can_field((string)($r['field']??'chuyenmon')))throw new RuntimeException('Bạn không có quyền xóa thông báo này.');$found=true;continue;}$kept[]=$r;}if(!$found)throw new RuntimeException('Không tìm thấy thông báo.');cds_notice_save_all($kept);$message='Đã xóa thông báo khỏi danh sách.';
        } else throw new RuntimeException('Thao tác không hợp lệ.');
        if($ajax){header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>true,'message'=>$message],JSON_UNESCAPED_UNICODE);exit;}
        flash($message,'success');
    }catch(Throwable $e){if($ajax){header('Content-Type: application/json; charset=utf-8');http_response_code(400);echo json_encode(['ok'=>false,'message'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);exit;}flash($e->getMessage(),'danger');}
    header('Location: '.BASE_URL.'admin.php?view=notices');exit;
}

$items=cds_notice_rows(); $fields=cds_notice_fields(); $teachers=[]; if(is_file(DATA_PATH.'/teachers.json')){$teachers=cds_json_load(DATA_PATH.'/teachers.json',[]);if(!is_array($teachers))$teachers=[];}
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thông báo – CDS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>body{background:#f4f7fb}.notice-shell{max-width:1450px}.field-badge{display:inline-flex;align-items:center;gap:.35rem;padding:.28rem .55rem;border-radius:999px;color:#fff;font-size:.75rem;font-weight:800}.notice-title{font-weight:800}.action-btn{width:38px;height:38px;padding:0;display:inline-grid;place-items:center}.progress-modal{position:fixed;inset:0;background:#0f172a99;display:none;place-items:center;z-index:9999}.progress-modal.show{display:grid}.progress-box{width:min(520px,calc(100% - 2rem));background:#fff;border-radius:18px;padding:1.35rem;box-shadow:0 24px 80px #0004}.progress{height:14px}.progress-bar{transition:width .15s}.file-current{font-size:.8rem}.table td{vertical-align:middle}@media(max-width:900px){.notice-grid{grid-template-columns:1fr!important}.table-responsive{font-size:.85rem}}</style></head><body>
<main class="container-fluid notice-shell py-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><a href="admin.php" class="text-decoration-none small"><i class="bi bi-arrow-left"></i> Trang tổng quan</a><h2 class="mt-1 mb-0"><i class="bi bi-megaphone-fill text-primary"></i> Thông báo</h2><p class="text-muted mb-0">Tạo và quản lý thông báo theo lĩnh vực được phân quyền.</p></div><a href="admin.php" class="btn btn-outline-secondary">Quay lại</a></div><?php show_flash();?><div class="notice-grid" style="display:grid;grid-template-columns:minmax(330px,.75fr) minmax(0,1.65fr);gap:1rem"><section class="card shadow-sm border-0"><div class="card-header bg-primary text-white fw-bold">Thêm / cập nhật thông báo</div><div class="card-body"><form id="noticeForm" method="post" enctype="multipart/form-data"><input type="hidden" name="notice_action" value="save"><input type="hidden" name="notice_ajax" value="1"><input type="hidden" name="id" id="n_id"><input type="hidden" name="file_path" id="n_file"><div class="mb-2"><label class="form-label fw-semibold">Lĩnh vực *</label><select class="form-select" name="field" id="n_field" required><?php foreach($allowedFields as $key=>$f):?><option value="<?=e($key)?>"><?=e($f['label'])?></option><?php endforeach;?></select><div class="form-text">Chỉ hiện các lĩnh vực bạn có quyền đăng.</div></div><div class="mb-2"><label class="form-label fw-semibold">Tiêu đề *</label><input class="form-control" name="title" id="n_title" required></div><div class="mb-2"><label class="form-label fw-semibold">Ngày ban hành / sự kiện</label><input class="form-control" type="date" name="date" id="n_date" value="<?=date('Y-m-d')?>"></div><div class="form-check mb-2"><input class="form-check-input" type="checkbox" name="has_deadline" value="1" id="n_deadline"><label class="form-check-label" for="n_deadline">Có hạn thực hiện / báo cáo</label></div><div class="mb-2" id="dueBox" hidden><label class="form-label fw-semibold">Hạn</label><input class="form-control" type="date" name="due_date" id="n_due"></div><div class="form-check mb-2"><input class="form-check-input" type="checkbox" name="has_assignees" value="1" id="n_assignee"><label class="form-check-label" for="n_assignee">Chỉ định người thực hiện</label></div><div class="mb-2" id="assigneeBox" hidden><label class="form-label fw-semibold">Người thực hiện</label><select class="form-select" name="assignees[]" id="n_assignees" multiple size="5"><?php foreach($teachers as $t):$name=trim((string)($t['name']??$t['teacher_name']??''));if($name==='')continue;?><option><?=e($name)?></option><?php endforeach;?></select></div><div class="mb-2"><label class="form-label fw-semibold">Nội dung</label><textarea class="form-control" rows="4" name="content" id="n_content"></textarea></div><div class="mb-2"><label class="form-label fw-semibold">Link (Drive, website…)</label><input class="form-control" type="url" name="link" id="n_link" placeholder="https://..."></div><div class="mb-2"><label class="form-label fw-semibold">File đính kèm</label><input class="form-control" type="file" name="file" id="n_upload"><div class="form-text">Tải trực tiếp lên Google Drive – tối đa 25 MB.</div><div class="file-current mt-1" id="currentFile"></div></div><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="completed" value="1" id="n_completed"><label class="form-check-label" for="n_completed">Đã hoàn thành</label></div><div class="d-grid gap-2"><button class="btn btn-primary" id="saveBtn"><i class="bi bi-cloud-arrow-up"></i> Lưu thông báo</button><button class="btn btn-outline-secondary" type="button" id="resetBtn">Làm mới</button></div></form></div></section><section class="card shadow-sm border-0"><div class="card-header fw-bold">Danh sách thông báo (<?=count($items)?>)</div><div class="table-responsive"><table class="table table-hover mb-0"><thead class="table-light"><tr><th>Ngày</th><th>Lĩnh vực</th><th>Tiêu đề</th><th>Hạn</th><th>Trạng thái</th><th>Tài liệu</th><th style="width:190px">Thao tác</th></tr></thead><tbody><?php foreach($items as $it):$fk=(string)($it['field']??'chuyenmon');$f=$fields[$fk]??$fields['chuyenmon'];$can=cds_notice_can_field($fk);?><tr><td><?=e((string)($it['date']??''))?></td><td><span class="field-badge" style="background:<?=e($f['color'])?>"><?=e($f['label'])?></span></td><td><div class="notice-title"><?=e((string)($it['title']??''))?></div><small class="text-muted"><?=e(mb_strimwidth(strip_tags((string)($it['content']??'')),0,100,'…','UTF-8'))?></small></td><td><?=e((string)($it['due_date']??'—'))?></td><td><?=!empty($it['completed'])?'<span class="badge text-bg-success">Hoàn thành</span>':'<span class="badge text-bg-warning">Đang theo dõi</span>'?></td><td><?php if(!empty($it['file_path'])):?><a class="btn btn-sm btn-outline-success" target="_blank" href="<?=e(cds_notice_file_url((string)$it['file_path']))?>"><i class="bi bi-paperclip"></i></a><?php endif;?><?php if(!empty($it['link'])):?><a class="btn btn-sm btn-outline-primary" target="_blank" href="<?=e((string)$it['link'])?>"><i class="bi bi-link-45deg"></i></a><?php endif;?></td><td><?php if($can):?><div class="d-flex gap-1"><form method="post"><input type="hidden" name="notice_action" value="toggle"><input type="hidden" name="id" value="<?=e((string)$it['id'])?>"><button class="btn btn-sm <?=!empty($it['completed'])?'btn-outline-warning':'btn-outline-success'?> action-btn" title="<?=!empty($it['completed'])?'Mở lại':'Hoàn thành'?>"><i class="bi <?=!empty($it['completed'])?'bi-arrow-counterclockwise':'bi-check-lg'?>"></i></button></form><button class="btn btn-sm btn-outline-secondary action-btn viewNotice" type="button" title="Xem" data-row='<?=e(json_encode($it,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?>'><i class="bi bi-eye"></i></button><button class="btn btn-sm btn-outline-primary action-btn editNotice" type="button" title="Sửa" data-row='<?=e(json_encode($it,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?>'><i class="bi bi-pencil"></i></button><form method="post" onsubmit="return confirm('Xóa thông báo này?')"><input type="hidden" name="notice_action" value="delete"><input type="hidden" name="id" value="<?=e((string)$it['id'])?>"><button class="btn btn-sm btn-outline-danger action-btn" title="Xóa"><i class="bi bi-trash"></i></button></form></div><?php endif;?></td></tr><?php endforeach;if(!$items):?><tr><td colspan="7" class="text-center text-muted py-5">Chưa có thông báo.</td></tr><?php endif;?></tbody></table></div></section></div></main>
<div class="progress-modal" id="progressModal"><div class="progress-box"><div class="d-flex align-items-center gap-3 mb-3"><div class="spinner-border text-primary" id="progressSpinner"></div><div><strong id="progressTitle">Đang tải văn bản…</strong><div class="text-muted small" id="progressText">Đang gửi file lên máy chủ.</div></div></div><div class="progress" role="progressbar"><div class="progress-bar progress-bar-striped progress-bar-animated" id="progressBar" style="width:0%">0%</div></div><div class="mt-3 text-end"><button class="btn btn-primary" type="button" id="progressClose" hidden>Đóng</button></div></div></div>
<div class="modal fade" id="viewModal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">Chi tiết thông báo</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="viewBody"></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>
const form=document.getElementById('noticeForm'),modal=document.getElementById('progressModal'),bar=document.getElementById('progressBar'),pt=document.getElementById('progressTitle'),px=document.getElementById('progressText'),spinner=document.getElementById('progressSpinner'),closeBtn=document.getElementById('progressClose');
function sync(){dueBox.hidden=!n_deadline.checked;assigneeBox.hidden=!n_assignee.checked}n_deadline.onchange=sync;n_assignee.onchange=sync;sync();
function setProgress(v,text){v=Math.max(0,Math.min(100,v));bar.style.width=v+'%';bar.textContent=v+'%';if(text)px.textContent=text}
form.addEventListener('submit',function(e){e.preventDefault();if(!form.reportValidity())return;modal.classList.add('show');spinner.hidden=false;closeBtn.hidden=true;pt.textContent=n_upload.files.length?'Đang tải văn bản lên Google Drive…':'Đang lưu thông báo…';setProgress(2,'Đang chuẩn bị dữ liệu…');const xhr=new XMLHttpRequest(),fd=new FormData(form);xhr.open('POST',location.href,true);xhr.upload.onprogress=function(ev){if(!ev.lengthComputable)return;setProgress(Math.min(92,Math.round(ev.loaded/ev.total*92)),'Đang tải file lên máy chủ…')};xhr.upload.onload=function(){setProgress(95,n_upload.files.length?'Máy chủ đang chuyển file vào Google Drive…':'Đang lưu dữ liệu…')};xhr.onload=function(){let d={};try{d=JSON.parse(xhr.responseText)}catch(e){}if(xhr.status>=200&&xhr.status<300&&d.ok){setProgress(100,'Hoàn tất.');pt.textContent=d.message||'Đã lưu thành công.';spinner.hidden=true;closeBtn.hidden=false;closeBtn.onclick=()=>location.reload()}else{setProgress(0,'Không thành công.');pt.textContent=d.message||'Có lỗi khi tải/lưu thông báo.';spinner.hidden=true;closeBtn.hidden=false;closeBtn.onclick=()=>modal.classList.remove('show')}};xhr.onerror=function(){setProgress(0,'Mất kết nối.');pt.textContent='Không kết nối được máy chủ.';spinner.hidden=true;closeBtn.hidden=false;closeBtn.onclick=()=>modal.classList.remove('show')};xhr.send(fd)});
resetBtn.onclick=function(){form.reset();n_id.value='';n_file.value='';currentFile.textContent='';sync()};
document.querySelectorAll('.editNotice').forEach(b=>b.onclick=function(){const r=JSON.parse(b.dataset.row||'{}');n_id.value=r.id||'';n_field.value=r.field||'chuyenmon';n_title.value=r.title||'';n_date.value=r.date||'';n_deadline.checked=!!r.has_deadline;n_due.value=r.due_date||'';n_assignee.checked=!!r.has_assignees;Array.from(n_assignees.options).forEach(o=>o.selected=(r.assignees||[]).includes(o.value));n_content.value=r.content||'';n_link.value=r.link||'';n_file.value=r.file_path||'';n_completed.checked=!!r.completed;currentFile.innerHTML=r.file_path?'Tệp hiện tại: <a target="_blank" href="'+(String(r.file_path).startsWith('gdrive:')?'admin.php?drive_file='+encodeURIComponent(String(r.file_path).slice(7)):'data/'+String(r.file_path).replace(/^\//,''))+'">Mở tệp</a>':'';sync();window.scrollTo({top:0,behavior:'smooth'})});
document.querySelectorAll('.viewNotice').forEach(b=>b.onclick=function(){const r=JSON.parse(b.dataset.row||'{}'),f=<?=json_encode($fields,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>[r.field||'chuyenmon']||{};viewBody.innerHTML='<div class="mb-2"><span class="field-badge" style="background:'+f.color+'">'+f.label+'</span></div><h4>'+String(r.title||'')+'</h4><div class="text-muted mb-3">'+String(r.date||'')+(r.due_date?' · Hạn '+r.due_date:'')+'</div><div style="white-space:pre-wrap">'+String(r.content||'')+'</div>';bootstrap.Modal.getOrCreateInstance(document.getElementById('viewModal')).show()});
</script></body></html>